}

function drawBall(px, py, size) {  // función propia
  fill(100, 150, 255); noStroke(); ellipse(px, py, size, size);
}

let total = 5, xs = [], speeds = [];

function setup() {
  createCanvas(400, 400);
  for (let i = 0; i < total; i++) {
    xs[i] = random(25, width - 25);  // posición inicial
    speeds[i] = random(1, 4);        // velocidad propia
  }
}

function draw() {
  background(220);
  for (let i = 0; i < total; i++) {
    xs[i] = xs[i] + speeds[i];
    if (xs[i] >= width - 15 || xs[i] <= 15) speeds[i] = -speeds[i];
    drawBall(xs[i], 100 + i * 50, 30);
  }
}

